// Comprehensive helper function to match tech string to authentic official SVG logo
export function getTechLogo(techName, className = "w-3.5 h-3.5") {
  if (!techName) return null;
  const name = techName.toLowerCase();

  // Deep Learning & Machine Learning
  if (name.includes('python')) return <PythonLogo className={className} />;
  if (name.includes('pytorch')) return <PyTorchLogo className={className} />;
  if (name.includes('tensorflow')) return <TensorFlowLogo className={className} />;
  if (name.includes('keras')) return <KerasLogo className={className} />;
  if (name.includes('opencv')) return <OpenCVLogo className={className} />;
  if (name.includes('scikit')) return <ScikitLearnLogo className={className} />;
  if (name.includes('yolo') || name.includes('ultralytics') || name.includes('gelan')) return <YOLOLogo className={className} />;
  if (name.includes('roboflow')) return <RoboflowLogo className={className} />;
  if (name.includes('lightgbm') || name.includes('catboost') || name.includes('boosting')) return <LightGBMLogo className={className} />;
  if (name.includes('pandas')) return <PandasLogo className={className} />;
  if (name.includes('numpy')) return <NumPyLogo className={className} />;
  if (name.includes('hugging') || name.includes('transformers')) return <HuggingFaceLogo className={className} />;
  if (name.includes('llama') || name.includes('meta')) return <MetaLogo className={className} />;
  if (name.includes('langchain')) return <LangChainLogo className={className} />;
  if (name.includes('rag') || name.includes('vector') || name.includes('llm') || name.includes('prompt')) return <LangChainLogo className={className} />;

  // BI, Data Analytics & Enterprise
  if (name.includes('power bi') || name.includes('power query')) return <PowerBILogo className={className} />;
  if (name.includes('looker') || name.includes('data studio')) return <LookerStudioLogo className={className} />;
  if (name.includes('n8n') || name.includes('workflow')) return <N8NLogo className={className} />;
  if (name.includes('isdp') || name.includes('huawei')) return <HuaweiLogo className={className} />;
  if (name.includes('oracle') || name.includes('oci')) return <OracleCloudLogo className={className} />;

  // Databases & Cloud
  if (name.includes('postgres')) return <PostgreSQLLogo className={className} />;
  if (name.includes('mysql') || name.includes('sql')) return <MySQLLogo className={className} />;
  if (name.includes('docker')) return <DockerLogo className={className} />;

  // Web & Frameworks
  if (name.includes('laravel')) return <LaravelLogo className={className} />;
  if (name.includes('php')) return <PHPLogo className={className} />;
  if (name.includes('flask')) return <FlaskLogo className={className} />;
  if (name.includes('fastapi')) return <FastAPILogo className={className} />;
  if (name.includes('streamlit')) return <StreamlitLogo className={className} />;
  if (name.includes('leaflet') || name.includes('gis') || name.includes('map')) return <LeafletLogo className={className} />;
  if (name.includes('react')) return <ReactLogo className={className} />;
  if (name.includes('tailwind')) return <TailwindCSSLogo className={className} />;
  if (name.includes('javascript') || name.includes('js') || name.includes('es6')) return <JavaScriptLogo className={className} />;
  if (name.includes('git') || name.includes('github')) return <GitLogo className={className} />;

  return null;
}
